#include <iostream>
#include <vector>
#include <string>
#include <mach/mach.h>
#include <servers/bootstrap.h>
#include "cheraxxx_ipc.h" // Generated by Mig

/*
 * MachInjector - Utility to inject tactical findings into the Cheraxxx Core via Mach RPC.
 * Used by the Ruby/Perl orchestration layer to bypass disk I/O.
 */

int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " <sender_id> <msg_type> <priority> <payload_file_or_string>" << std::endl;
        return 1;
    }

    int sender_id = std::stoi(argv[1]);
    int msg_type = std::stoi(argv[2]);
    int priority = std::stoi(argv[3]);
    std::string payload = argv[4];

    // Check if payload is a file path or direct string
    if (payload.size() > 0 && payload[0] == '@') {
        // Implementation for reading from file if needed,
        // but for zero-latency we prefer direct string passing from pipe.
    }

    mach_port_t server_port;
    kern_return_t kr = bootstrap_look_up(bootstrap_port, "com.cheraxxx.tactical", &server_port);
    if (kr != KERN_SUCCESS) {
        std::cerr << "Failed to look up cheraxxx tactical port: " << mach_error_string(kr) << std::endl;
        return 1;
    }

    // Ensure payload fits in Mig definition (tact_msg_payload_t is array[*:1024] of char)
    // Note: Mig handles variable size arrays if defined with *,
    // but our current .defs has [*:1024].

    kr = cheraxxx_dispatch_tactical_node(server_port, sender_id, msg_type, priority, (char*)payload.c_str(), payload.size());

    if (kr != KERN_SUCCESS) {
        std::cerr << "Mach RPC call failed: " << mach_error_string(kr) << std::endl;
        return 1;
    }

    return 0;
}
